22	type AvatarAction =
23	  | { type: 'claim' }
24	  | { type: 'sign-in' }
25	  | {
26	      type: 'switch';
27	      previousReceiptUserId: string;
28	      previousDisplayName: string;
29	    }
30	  | null;
