32	function getAvatarAction(
33	  assignment: Assignment,
34	  allAssignments: readonly Assignment[] | undefined,
35	  clerkUserId: string | null | undefined
36	): AvatarAction {
37	  if (assignment.receiptUser?.userId != null) return null;
38	  if (clerkUserId == null) return { type: 'sign-in' };
