41	  const currentUserClaimed = assignments.find(
42	    (a) => a.receiptUser?.user?.authUserId === clerkUserId
43	  );
44	
45	  if (currentUserClaimed == null) return { type: 'claim' };
46	  return {
47	    type: 'switch',
