                          : action.type === 'switch'
                            ? t`Switch to ${displayName}`
                            : t`Claim ${displayName}`
                      }
                      title={
                        action.type === 'sign-in'
                          ? t`Sign in to claim ${displayName}`
                          : action.type === 'switch'
                            ? t`Switch to ${displayName}`
                            : t`Claim ${displayName}`
                      }
                    >
                      <Avatar
                        key={assignment.id}
                        className={cn('ring-1', c.ring)}
                        title={displayName}
                      >
                        <AvatarFallback className={cn(c.bg, c.text)}>
                          <HandGrab />
                        </AvatarFallback>
                      </Avatar>
                    </Button>
